function idb(){return new Promise((ok,fail)=>{const req=indexedDB.open('homekind-secure-access',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('keys'))req.result.createObjectStore('keys');};req.onsuccess=()=>ok(req.result);req.onerror=()=>fail(req.error);});}
async function keyStore(method,key){const db=await idb();return new Promise((ok,fail)=>{const t=db.transaction('keys',method==='get'?'readonly':'readwrite');const req=method==='get'?t.objectStore('keys').get('privateAccessKey'):method==='put'?t.objectStore('keys').put(key,'privateAccessKey'):t.objectStore('keys').delete('privateAccessKey');req.onsuccess=()=>ok(req.result);req.onerror=()=>fail(req.error);t.oncomplete=()=>db.close();});}
function b64ToBytes(s){const b=atob(s);return Uint8Array.from(b,c=>c.charCodeAt(0));}
async function readPrivateKey(file){if(!file||file.size>20_000)throw Error('Choose the private PEM key supplied with this app.');const txt=await file.text();const key=txt.match(/-----BEGIN PRIVATE KEY-----([\s\S]*?)-----END PRIVATE KEY-----/);if(!key)throw Error('The selected file is not a PKCS#8 private key.');return crypto.subtle.importKey('pkcs8',b64ToBytes(key[1].replace(/\s/g,'')),{name:'RSA-OAEP',hash:'SHA-256'},false,['decrypt']);}
