async function loadEncrypted(key){const r=await fetch('./data/snapshot.enc.json',{cache:'no-store'});if(!r.ok)throw Error('Encrypted rental snapshot could not be loaded.');const packet=await r.json();const p=await decryptSnapshot(packet,key);loadDataset(p);return p;}
function loadDataset(p){if(!p||!Array.isArray(p.listings)||p.listings.length===0||p.listings.length>500000)throw Error('Invalid private rental dataset');const seen=new Set();const rows=[];for(const a of p.listings){if(!a||typeof a.id!=='string'||seen.has(a.id))continue;seen.add(a.id);const r={...a,city:normalizeCity(a.city),rent:a.rent==null?null:Number(a.rent),beds:a.beds==null?null:Number(a.beds),baths:a.baths==null?null:Number(a.baths),sqft:a.sqft==null?null:Number(a.sqft),distance:a.distance==null?null:Number(a.distance),lat:a.lat==null?null:Number(a.lat),lng:a.lng==null?null:Number(a.lng)};r.photos=(Array.isArray(a.photos)&&['display-and-process','display-allowed'].includes(a.photoRights))?a.photos.filter(x=>safeUrl(x)).slice(0,12):[];rows.push(r);}
    const prev=loadStored('previousIds',[]);const prevSet=new Set(prev);S.newIds=prev.length?rows.filter(r=>!prevSet.has(r.id)).map(x=>x.id):[];
    S.data=p;S.listings=rows;S.benchmarks=Array.isArray(p.benchmarks)?p.benchmarks:[];S.dbUnlocked=true;
    persist('previousIds',rows.map(x=>x.id));persist('lastSnapshotAt',p.createdAt||new Date().toISOString());
    $('status-light').classList.add('ready');$('sidebar-data-status').textContent=`${rows.length.toLocaleString()} private listings`;
    $('top-data-label').textContent='Data unlocked';$('nav-count').textContent=rows.length.toLocaleString();
    renderCurrent();if(S.newIds.length)toast(`${S.newIds.length} newly collected listings in the updated snapshot.`);
}
